drop table CHB_INTERF_CONFIG;
CREATE TABLE
    CHB_INTERF_CONFIG
    (
        INTERF_ID VARCHAR2(50) NOT NULL,
        LAST_UPDATETIME TIMESTAMP(6),
        REMARK VARCHAR2(128),
        INTERF_NAME VARCHAR2(64),
        CONTENT_TYPE CHAR(1),
        CONTENT_SRC VARCHAR2(8),
        REF_REPORT VARCHAR2(1024),
        SYS_SCOPE VARCHAR2(20),
        STATUS VARCHAR2(20)
    );
COMMENT ON TABLE CHB_INTERF_CONFIG
IS
    '中债接口数据更新时间表';
COMMENT ON COLUMN CHB_INTERF_CONFIG.INTERF_ID
IS
    '接口代码';
COMMENT ON COLUMN CHB_INTERF_CONFIG.LAST_UPDATETIME
IS
    '最近更新时间';
COMMENT ON COLUMN CHB_INTERF_CONFIG.REMARK
IS
    '备注';
COMMENT ON COLUMN CHB_INTERF_CONFIG.INTERF_NAME
IS
    '接口名称';
COMMENT ON COLUMN CHB_INTERF_CONFIG.CONTENT_TYPE
IS
    '内容类型：F－全量，I－增量';
COMMENT ON COLUMN CHB_INTERF_CONFIG.CONTENT_SRC
IS
    '内容来源：X-XML文件,T-TXT文件,D－数据库';
COMMENT ON COLUMN CHB_INTERF_CONFIG.REF_REPORT
IS
    '影响的报表，以分号分割';
COMMENT ON COLUMN CHB_INTERF_CONFIG.SYS_SCOPE
IS
    '适用范围，按照中债、人行、信批设置1，或者0';
COMMENT ON COLUMN CHB_INTERF_CONFIG.STATUS
IS
    '有效状态，E－有效，D－删除';


